    int sign = 1;
    if (i < s.size() && (s[i] == '+' || s[i] == '-')) {
        if (s[i] == '-') sign = -1;
        i++;
    }
    long long value = 0;
    while (i < s.size() && s[i] >= '0' && s[i] <= '9') {
